import{_ as e,o,c as a,a3 as r}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Customer Portal","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Customer Portal | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/customer-portal"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Customer Portal | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/customer-portal"}]]},"headers":[],"relativePath":"user-guide/customer-portal.md","filePath":"user-guide/customer-portal.md","lastUpdated":1791287103000}'),s={name:"user-guide/customer-portal.md"};function n(i,t,c,d,l,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="customer-portal" tabindex="-1">Customer Portal <a class="header-anchor" href="#customer-portal" aria-label="Permalink to &quot;Customer Portal&quot;">​</a></h1><p>Install <strong>Customer Portal</strong> from Marketplace (free <strong>Operations</strong> module). It requires <strong>Contacts</strong>. Until it is installed, the Customer Portal nav stays hidden.</p><h2 id="invite-a-customer" tabindex="-1">Invite a customer <a class="header-anchor" href="#invite-a-customer" aria-label="Permalink to &quot;Invite a customer&quot;">​</a></h2><ol><li>Open a Contact that has an <strong>email</strong>.</li><li>On the contact record, use <strong>Invite to portal</strong> (needs <code>customer-portal.invite</code>).</li><li>The contact receives an email with a link to <code>/#/portal/invite/{token}</code> to set a password.</li><li>They sign in at <code>/#/portal/login</code> with email + password.</li></ol><p>On a <strong>shared</strong> app host (not a tenant subdomain), login asks for <strong>email first</strong>, then a searchable <strong>company/workspace</strong> list of only the workspaces that already invited that email. Invitation and reset emails still include <code>?workspace=</code> so most customers skip the picker. On a tenant-bound domain the workspace step is hidden.</p><p>From <strong>Operations → Customer Portal</strong> you can list accounts, resend invites, disable, or enable access (<code>customer-portal.manage</code> for disable/enable).</p><h2 id="what-customers-see" tabindex="-1">What customers see <a class="header-anchor" href="#what-customers-see" aria-label="Permalink to &quot;What customers see&quot;">​</a></h2><p>After login, the portal shell shows sections only when the related workspace module is installed:</p><table tabindex="0"><thead><tr><th>Section</th><th>Module</th><th>Actions</th></tr></thead><tbody><tr><td>Invoices</td><td><code>invoices</code></td><td>List, view, download PDF</td></tr><tr><td>Payments</td><td><code>payments</code></td><td>List, view, download receipt PDF</td></tr><tr><td>Quotations</td><td><code>quotations</code></td><td>List, view, PDF, get accept link</td></tr><tr><td>Contracts</td><td><code>contracts</code></td><td>List, view, PDF, get accept link</td></tr><tr><td>Support</td><td><code>help-desk</code></td><td>List, open ticket, add notes</td></tr></tbody></table><p>Visibility is limited to the Contact’s own records, or records for their Company when <code>company_id</code> is set. Contracts resolve via the linked Opportunity’s party.</p><p>One-shot e-sign pages (<code>/#/accept/quotations|contracts/...</code>) still work without a portal login.</p><h2 id="staff-vs-portal" tabindex="-1">Staff vs portal <a class="header-anchor" href="#staff-vs-portal" aria-label="Permalink to &quot;Staff vs portal&quot;">​</a></h2><ul><li>Staff use the normal workspace app and Spatie permissions.</li><li>Portal users never receive <code>invoices.view</code> or other staff permissions.</li><li>Disabling a portal account blocks login without deleting the Contact.</li></ul><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h2><p>Projects, tasks, magic-link login, and public Knowledge Base are not in <strong>1.0.0</strong> — see the <a href="/user-guide/customer-portal-overview">overview</a> and <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p>',15)])])}const u=e(s,[["render",n]]);export{h as __pageData,u as default};
